const c="c87fcceca464199c535b2599866aaca9";class n{async getWeather(r){try{const t=await fetch(`https://api.weatherapi.com/v1/forecast.json?key=${c}&q=${r}&days=3&aqi=no`);if(!t.ok)throw new Error("Weather API failed");const e=await t.json(),a=e.current,o=e.forecast.forecastday[0];return{temperature:a.temp_c,humidity:a.humidity,rainfall:o.day.totalprecip_mm,forecast:o.day.condition.text,condition:a.condition.text,windSpeed:a.wind_kph}}catch(t){return console.error("Error fetching weather:",t),null}}async getDetailedForecast(r,t=7){try{console.log(`🌤️ Fetching ${t}-day forecast for ${r}...`);const e=await fetch(`https://api.weatherapi.com/v1/forecast.json?key=${c}&q=${r}&days=${t}&aqi=no&alerts=yes`);if(!e.ok){const o=await e.text();throw console.error("Weather API error:",o),new Error(`Weather API failed: ${e.status}`)}const a=await e.json();return console.log("✅ Weather forecast fetched successfully"),a}catch(e){return console.error("Error fetching detailed forecast:",e),null}}async getWeatherByCoordinates(r,t){const e=`${r},${t}`;return this.getWeather(e)}async getDetailedForecastByCoordinates(r,t,e=7){const a=`${r},${t}`;return this.getDetailedForecast(a,e)}}const i=new n;export{n as WeatherService,i as weatherService};
